using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Data;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using PeerChatDesktop;
class PendingPhotoTest {
    static void Check(bool value,string why){if(!value)throw new Exception(why);}
    static IEnumerable<T> Descendants<T>(DependencyObject root) where T:DependencyObject {if(root is T)yield return (T)root;foreach(var child in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var value in Descendants<T>(child))yield return value;}
    static BitmapSource Picture(int width,int height){var pixels=new byte[width*height*3];for(int y=0;y<height;y++)for(int x=0;x<width;x++){int at=(y*width+x)*3;pixels[at]=(byte)(50+x*150/width);pixels[at+1]=(byte)(70+y*160/height);pixels[at+2]=(byte)(180-x*90/width);}var image=BitmapSource.Create(width,height,96,96,PixelFormats.Bgr24,null,pixels,width*3);image.Freeze();return image;}
    static void Snapshot(MessageModel model,string path){var card=new AttachmentCard{DataContext=model,Transfer=model.Attachment};var bubble=new MessageBubble{DataContext=model,Background=model.Bubble,CornerRadius=new CornerRadius(15),Padding=model.BubblePadding,HorizontalAlignment=HorizontalAlignment.Right,VerticalAlignment=VerticalAlignment.Top,Child=card,Margin=new Thickness(20)};var window=new Window{Width=440,Height=650,WindowStyle=WindowStyle.None,ShowInTaskbar=false,Background=new SolidColorBrush(Color.FromRgb(12,17,22)),Content=bubble};window.Show();window.UpdateLayout();var bitmap=new RenderTargetBitmap(440,650,96,96,PixelFormats.Pbgra32);bitmap.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var output=File.Create(path))encoder.Save(output);window.Close();}
    static void State(){
        var source=new LocalAttachmentSource("photo.png",ClipboardAttachments.EncodePng(Picture(30,50)),Picture(30,50));
        bool scope=true;int sends=0,binds=0,stops=0;var gate=new TaskCompletionSource<string>();
        var pending=new PendingOutgoingAttachment(source,()=>scope,()=>{sends++;return gate.Task;},id=>{Check(id=="native-id","wrong cancel target");stops++;return Task.CompletedTask;},id=>binds++);
        var running=pending.RunAsync();pending.BeginNativeAdmission();Check(pending.NativeAdmissionInFlight,"in-flight native admission allowed early polling projection");Check(!running.IsCompleted&&pending.Running&&pending.Status=="Preparing"&&pending.AcceptedId==null,"send completion was invented before native admission");
        pending.RunAsync().GetAwaiter().GetResult();Check(sends==1,"double send during admission");pending.CancelAsync().GetAwaiter().GetResult();Check(stops==0&&pending.Status=="Canceling","in-flight cancel assumed native admission");gate.SetResult("native-id");running.GetAwaiter().GetResult();Check(!pending.NativeAdmissionInFlight&&stops==1&&binds==1&&pending.AcceptedId=="native-id"&&!pending.CanRetry,"admission/cancel race duplicated send or failed to cancel the accepted job");
        int attempts=0;var retry=new PendingOutgoingAttachment(source,()=>scope,()=>{if(++attempts==1)throw new IOException("disk full");return Task.FromResult("retry-native");},id=>Task.CompletedTask,id=>{});
        retry.RunAsync().GetAwaiter().GetResult();Check(retry.Status=="Failed to send"&&retry.Error=="disk full"&&retry.CanRetry,"queue failure lost source or retry");retry.RunAsync().GetAwaiter().GetResult();Check(attempts==2&&retry.AcceptedId=="retry-native"&&!retry.CanRetry,"retry did not bind exactly one accepted ID");
        var lateGate=new TaskCompletionSource<string>();var stale=new PendingOutgoingAttachment(source,()=>scope,()=>lateGate.Task,id=>Task.CompletedTask,id=>binds++);int before=binds;var staleRun=stale.RunAsync();scope=false;lateGate.SetResult("old-account");staleRun.GetAwaiter().GetResult();Check(binds==before&&!stale.CanRetry,"late old-account admission mutated current presentation");int forbidden=0;var blocked=new PendingOutgoingAttachment(source,()=>scope,()=>{forbidden++;return Task.FromResult("bad");},id=>Task.CompletedTask,id=>{});blocked.RunAsync().GetAwaiter().GetResult();Check(forbidden==0&&blocked.Status=="Not sent","stale scope dispatched a send");
        scope=true;var preparation=new TaskCompletionSource<bool>();PendingOutgoingAttachment beforeRpc=null;beforeRpc=new PendingOutgoingAttachment(source,()=>scope,async()=>{await preparation.Task;if(beforeRpc.CancelRequested)return "";forbidden++;return "bad";},id=>Task.CompletedTask,id=>{});var prepareRun=beforeRpc.RunAsync();beforeRpc.CancelAsync().GetAwaiter().GetResult();preparation.SetResult(true);prepareRun.GetAwaiter().GetResult();Check(forbidden==0&&beforeRpc.Status=="Canceled"&&beforeRpc.CanRetry,"pre-admission cancel dispatched or lost source");
    }
    static void Projection(){
        var source=new LocalAttachmentSource("photo.png",new byte[]{1},Picture(30,50));
        var accepted=new PendingOutgoingAttachment(source,()=>true,()=>Task.FromResult("transfer-id"),id=>Task.CompletedTask,id=>{});accepted.RunAsync().GetAwaiter().GetResult();
        var conversation=new ConversationModel{Contact=new ContactData{peer="peer"}};var message=new MessageModel{Data=new MessageData{id="local-message",time=1},Outgoing=true,PendingAttachment=accepted,LocalAttachment=source};message.SetAttachment(new CoreAdapter.FileTransferData{id="transfer-id",logicalId="local-message",name="photo.png",size=10,state=0,sending=true});conversation.Messages.Add(message);
        var row=new CoreAdapter.FileTransferData{id="transfer-id",logicalId="different-native-message-id",name="photo.png",size=10,state=0,sending=true,time=50};Check(ChatAttachmentProjection.Apply(conversation,row)&&conversation.Messages.Count==1&&Object.ReferenceEquals(message,conversation.Messages[0])&&message.Data.id==row.logicalId&&message.PendingAttachment==null&&message.Attachment.logicalId==row.logicalId&&message.LocalAttachment==source,"DM snapshot duplicated/replaced bubble or lost its local original");Check(!ChatAttachmentProjection.Apply(conversation,row),"stable native snapshot changed reconciled DM bubble");
        var group=new GroupModel{Data=new GroupData{id="group",name="group"}};var groupPending=new PendingOutgoingAttachment(source,()=>true,()=>Task.FromResult("group-transfer"),id=>Task.CompletedTask,id=>{});groupPending.RunAsync().GetAwaiter().GetResult();var groupMessage=new MessageModel{Data=new MessageData{id="group-local",time=1},Outgoing=true,PendingAttachment=groupPending,LocalAttachment=source};groupMessage.SetGroupAttachment(new CoreAdapter.GroupAttachmentData{id="group-transfer",logicalId="group-local",group=group.Id,name="photo.png",size=10,state="preparing",sending=true},null);group.Messages.Add(groupMessage);var groupRow=new CoreAdapter.GroupAttachmentData{id="group-transfer",logicalId="group-transfer",group=group.Id,name="photo.png",size=10,state="uploading",sending=true,time=60};Check(GroupAttachmentProjection.Apply(group,groupRow)&&group.Messages.Count==1&&Object.ReferenceEquals(groupMessage,group.Messages[0])&&groupMessage.Data.id=="group-transfer"&&groupMessage.PendingAttachment==null&&groupMessage.LocalAttachment==source,"group reconciliation duplicated bubble or lost preview");
    }
    static void Images(string root){
        var portrait=Picture(600,1000);var bytes=ClipboardAttachments.EncodePng(portrait);var source=new LocalAttachmentSource("portrait.png",bytes,ClipboardAttachments.Preview(portrait));Check(source.Preview.PixelHeight==480&&source.Preview.PixelWidth==288,"portrait preview lost its aspect ratio or remained tiny");var original=source.OpenImageAsync().GetAwaiter().GetResult();Check(original.PixelWidth==600&&original.PixelHeight==1000,"pending local viewer opened only the thumbnail");source.PersistAsync(root).GetAwaiter().GetResult();Check(File.ReadAllBytes(source.Path).SequenceEqual(bytes)&&source.Unchanged(),"durable clipboard source changed exact PNG bytes");original=source.OpenImageAsync().GetAwaiter().GetResult();Check(original.PixelWidth==600&&original.PixelHeight==1000,"durable local viewer lost original dimensions");
        var model=new MessageModel{Data=new MessageData{id="portrait",time=1},Outgoing=true,LocalAttachment=source};model.SetAttachment(new CoreAdapter.FileTransferData{id="portrait",name="portrait.png",size=bytes.Length,sending=true,state=3,done=bytes.Length/2});
        var card=new AttachmentCard{DataContext=model,Transfer=model.Attachment};var surface=card.Children.OfType<Grid>().First();Check(surface.Width==288&&surface.Height==480,"large portrait image cropped or did not fill its area");Check(card.Children.OfType<TextBlock>().Count()==0&&model.GenericAttachmentFooter==Visibility.Collapsed&&model.BubblePadding==new Thickness(0),"photo kept generic filename/header/footer");var details=card.Children.OfType<StackPanel>().Single();Check(details.Visibility==Visibility.Collapsed,"photo details initially expanded");var footer=card.Children.OfType<Grid>().Skip(1).Single();var click=new MouseButtonEventArgs(Mouse.PrimaryDevice,0,MouseButton.Left){RoutedEvent=Mouse.MouseUpEvent};footer.RaiseEvent(click);Check(click.Handled&&model.IsExpanded,"footer did not independently expand details");Check(card.Children.OfType<StackPanel>().Single().Visibility==Visibility.Visible,"photo details not visible after footer click");model.IsExpanded=false;Snapshot(model,Path.Combine(root,"windows-photo-portrait.png"));
        var landscape=Picture(1000,600);var landscapeSource=new LocalAttachmentSource("landscape.png",ClipboardAttachments.EncodePng(landscape),ClipboardAttachments.Preview(landscape));var landscapeModel=new MessageModel{Data=new MessageData{id="landscape",time=1},Outgoing=true,LocalAttachment=landscapeSource};landscapeModel.SetAttachment(new CoreAdapter.FileTransferData{id="landscape",name="landscape.png",size=2048,sending=true,state=3,done=1024});var landscapeCard=new AttachmentCard{DataContext=landscapeModel,Transfer=landscapeModel.Attachment};surface=landscapeCard.Children.OfType<Grid>().First();Check(surface.Width==360&&surface.Height==216,"landscape preview was cropped");Snapshot(landscapeModel,Path.Combine(root,"windows-photo-landscape.png"));
        var waiting=new TaskCompletionSource<string>();var pending=new PendingOutgoingAttachment(source,()=>true,()=>waiting.Task,id=>Task.CompletedTask,id=>{});var pendingModel=new MessageModel{Data=new MessageData{id="pending",time=1},Outgoing=true,LocalAttachment=source,PendingAttachment=pending};pendingModel.SetAttachment(new CoreAdapter.FileTransferData{id="local",name=source.Name,size=source.Size,state=0,sending=true});Check(pendingModel.CompactStatus=="Preparing","pending photo showed sent/delivered");Snapshot(pendingModel,Path.Combine(root,"windows-photo-pending.png"));
        int opens=0;var interaction=new StackPanel();var interactionBubble=new MessageBubble{DataContext=model,Child=interaction};model.IsExpanded=false;PhotoAttachmentPresentation.Render(interaction,model,source.Preview,source.Name,source.Size,"Preparing",()=>opens++,null,null);var picture=interaction.Children.OfType<Grid>().First();var photoClick=new MouseButtonEventArgs(Mouse.PrimaryDevice,0,MouseButton.Left){RoutedEvent=Mouse.MouseUpEvent};picture.RaiseEvent(photoClick);Check(opens==1&&!model.IsExpanded,"picture click also expanded details through its bubble");var interactionFooter=interaction.Children.OfType<Grid>().Skip(1).Single();interactionFooter.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice,0,MouseButton.Left){RoutedEvent=Mouse.MouseUpEvent});Check(opens==1&&model.IsExpanded,"footer click opened image or toggled details twice through its bubble");model.IsExpanded=false;
        var text=new MessageModel{Data=new MessageData{id="text",text="hello",time=1},Outgoing=true};Check(text.Text=="hello"&&text.TextVisibility==Visibility.Visible&&text.BubblePadding==new Thickness(12,8,12,8)&&text.GenericAttachmentFooter==Visibility.Visible&&text.CompactStatus=="Queued"&&text.GenericExpandedVisibility==Visibility.Collapsed,"ordinary text presentation changed");
        string file=Path.Combine(root,"changed.png");File.WriteAllBytes(file,bytes);var selected=new LocalAttachmentSource(file,bytes.Length);File.SetLastWriteTimeUtc(file,File.GetLastWriteTimeUtc(file).AddSeconds(10));Check(!selected.Unchanged(),"same-size modified source was accepted");
    }
    [STAThread] static int Main(string[] args){try{new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Directory.CreateDirectory(args[0]);State();Projection();Images(args[0]);Console.WriteLine("PASS: pending attachment scope, retry, cancel/admission race, native ID reconciliation, local originals, aspect ratio, image footer, ordinary text.");return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
